_file_map = {

    "bookConditionData.baml": "enum BookConditionEnum {\r\n    BARU @alias(\"c1\") @description(#\"\r\n        The book is in brand new condition, with no visible wear or damage. Often still in original shrink wrap, or in the case where the no shrinkwarp present, it is clear that special preservation and storage measures have been done to keep the book pristine.\r\n    \"#)\r\n    SANGAT_BAIK @alias(\"c2\") @description(#\" \r\n        The book is in excellent condition, showing almost no or minimal signs of wear. It has no shrink wrap but looks almost new. The pages are clean and intact, and the cover is in great shape with no visible defects or discoloration.\r\n    \"#)\r\n    BAIK @alias(\"c3\") @description(#\"\r\n        The book is in very good condition, with some minor wear but no major defects. Pages are clean and intact, and the cover may have slight signs of use but is still in great shape.\r\n    \"#)\r\n    CUKUP_BAIK @alias(\"c4\") @description(#\"\r\n        The book is in good condition, with noticeable wear and defects. Texts are perfectly readable, and the book is still fully intact. The colors on the cover may be slightly faded, but there are no major damages. The pages may be slightly yellowed due to age, but the prints are still clear and legible.\r\n    \"#)\r\n    DITERIMA @alias(\"c5\") @description(#\"\r\n        The book is heavily damaged, with significant wear, major defects, tears or signs of water, mold and other damage. Some text may be missing or illegible, but the some texts are still readable, and one can still infer the metadata of the book (title, author, publisher, and/or year) from the remaining text.\r\n    \"#)\r\n    BURUK @alias(\"c6\") @description(#\"\r\n        The book is in extremely poor condition. Pages are torn, missing or is too deteriorated by water and other damages, that may caused the prints to be blurry and fading. It is barely readable and the metadata of the book cannot be inferred.\r\n    \"#)\r\n}\r\n\r\nenum BookPrintTypeEnum {\r\n    HARDCOVER @alias(\"pt1\") @description(\"The book has a hard cover.\")\r\n    PAPERBACK @alias(\"pt2\") @description(\"The book has a soft cover.\")\r\n    FOTOKOPI @alias(\"pt3\") @description(\"The book is a photocopy or printout.\")\r\n}\r\n\r\nclass PhysicalObservation {\r\n    imageNumber int @description(\"The index number of the image this observation comes from\")\r\n    bookComponent string @description(\"Which part of the book (e.g., 'front cover', 'back cover', 'spine', 'pages', 'binding', 'edges')\")\r\n    observedFeatures string[] @description(#\"\r\n        List of specific physical features observed:\r\n        - Discoloration (yellowing, fading, staining)\r\n        - Structural damage (tears, creases, bent corners, warping)\r\n        - Water damage (water stains, rippling, warping)\r\n        - Biological damage (mold, mildew, foxing, insect damage)\r\n        - Wear patterns (edge wear, scuffing, scratches)\r\n        - Binding condition (loose, tight, broken, intact)\r\n        - Page condition (brittle, yellowed, clean, intact)\r\n        - Print quality (clear, faded, smudged, legible)\r\n        - Preservation indicators (shrink wrap, dust jacket, protective covering)\r\n    \"#)\r\n    severityLevel string @description(\"Severity of issues observed: 'none', 'minimal', 'minor', 'moderate', 'major', 'severe', 'critical'\")\r\n    readabilityImpact string @description(\"How the observed damage affects text readability: 'no impact', 'slight impact', 'moderate impact', 'significant impact', 'severe impact', 'illegible'\")\r\n}\r\n\r\nclass ConditionAnalysis {\r\n    overallAssessment string @description(#\"\r\n        Comprehensive assessment of the book's physical condition:\r\n        - Summary of all observed damage and wear\r\n        - Evaluation of structural integrity\r\n        - Assessment of readability and usability\r\n        - Notable preservation or deterioration factors\r\n        - Comparison across all images\r\n    \"#)\r\n    \r\n    conditionReasoning string @description(#\"\r\n        Detailed reasoning for condition classification:\r\n        - Why this condition level was chosen\r\n        - Key factors that determined the classification\r\n        - Comparison with condition enum descriptions\r\n        - Edge cases or borderline considerations\r\n        - Supporting evidence from observations\r\n    \"#)\r\n    \r\n    preservationUrgency string @description(#\"\r\n        Assessment of preservation urgency: 'none needed', 'routine care', 'preventive measures', 'immediate attention', 'critical intervention required'\r\n        Explain what factors contribute to this urgency level.\r\n    \"#)\r\n}\r\n\r\nclass PrintTypeAnalysis {\r\n    coverMaterial string @description(\"Observed cover material: 'rigid cardboard/board', 'flexible card stock', 'paper', 'cloth', 'leather', 'synthetic material', 'unknown'\")\r\n    \r\n    bindingType string @description(\"Observed binding type: 'sewn binding', 'perfect binding (glued)', 'saddle stitch (stapled)', 'spiral bound', 'loose leaf', 'unknown'\")\r\n    \r\n    printQualityIndicators string[] @description(#\"\r\n        Observable indicators of print type:\r\n        - Professional printing (even ink, high quality paper, commercial binding)\r\n        - Photocopy indicators (uneven ink density, copy artifacts, simple binding)\r\n        - Paper quality (coated, uncoated, recycled, newsprint, premium)\r\n        - Cover finish (glossy, matte, laminated, unfinished)\r\n        - Spine construction (professionally bound, stapled, glued, sewn)\r\n        - Overall production quality\r\n    \"#)\r\n    \r\n    printTypeReasoning string @description(#\"\r\n        Detailed reasoning for print type classification:\r\n        - Why this print type was chosen\r\n        - Key visual indicators that support this classification\r\n        - Comparison with print type enum descriptions\r\n        - Any ambiguous factors considered\r\n    \"#)\r\n}\r\n\r\nclass BookConditionData {\r\n    // Chain-of-thought reasoning fields\r\n    physicalObservations PhysicalObservation[] @description(#\"\r\n        Document ALL physical observations from each image:\r\n        - Systematically examine each book component visible\r\n        - List specific features and damage observed\r\n        - Rate severity of each issue\r\n        - Assess impact on readability\r\n        Document observations for each image separately to enable cross-validation.\r\n    \"#)\r\n    \r\n    conditionAnalysis ConditionAnalysis @description(#\"\r\n        Comprehensive analysis of the book's physical condition:\r\n        - Synthesize observations into overall assessment\r\n        - Explain reasoning for condition classification\r\n        - Evaluate preservation urgency\r\n        This guides the final condition classification.\r\n    \"#)\r\n    \r\n    printTypeAnalysis PrintTypeAnalysis @description(#\"\r\n        Analysis of the book's print type and construction:\r\n        - Examine cover material and binding\r\n        - Identify print quality indicators\r\n        - Explain reasoning for print type classification\r\n        This guides the final print type classification.\r\n    \"#)\r\n    \r\n    // Final classification fields\r\n    Condition BookConditionEnum @description(#\"\r\n        Final condition classification based on the detailed analysis above.\r\n        Must align with the conditionAnalysis reasoning and observed damage severity.\r\n    \"#)\r\n    \r\n    PrintType BookPrintTypeEnum @description(#\"\r\n        Final print type classification based on the detailed analysis above.\r\n        Must align with the printTypeAnalysis reasoning and observed construction features.\r\n    \"#)\r\n}\r\n\r\nfunction GetBookConditionData(MultiImages: image[], bookId: string) -> BookConditionData {\r\n    client \"Gemini20FlashLite\"\r\n    prompt #\"\r\n        You are an expert book conservator and preservation specialist with extensive experience in assessing the physical condition of books and manuscripts. Your expertise includes identifying various types of damage, evaluating deterioration patterns, and recommending appropriate preservation measures. You are working on a national library cataloguing and preservation project.\r\n\r\n        CONTEXT:\r\n        Book ID: {{bookId}}\r\n        You have received {{MultiImages|length}} image(s) showing different aspects of this book. Your assessment will guide preservation decisions and resource allocation for conservation efforts. All images are guaranteed to be of the same book.\r\n\r\n        YOUR MISSION:\r\n        Conduct a systematic, evidence-based assessment of the book's physical condition and print type. Your analysis will directly impact preservation planning, so accuracy and thoroughness are critical.\r\n\r\n        ANALYTICAL WORKFLOW - FOLLOW THESE STEPS SEQUENTIALLY:\r\n\r\n        {% set total_images = MultiImages|length %}\r\n        \r\n        STEP 1: SYSTEMATIC PHYSICAL EXAMINATION                                      ║\r\n        \r\n        Examine each of the {{total_images}} image(s) systematically, documenting all physical observations:\r\n        \r\n        {% for image in MultiImages %}\r\n        IMAGE {{loop.index}} of {{total_images}}:\r\n        \r\n        For this image, conduct a component-by-component examination:\r\n        \r\n        COVER EXAMINATION:\r\n        Front Cover:\r\n        - Surface condition: discoloration, fading, staining\r\n        - Structural integrity: tears, creases, dents, warping\r\n        - Corner condition: bent, rounded, torn, intact\r\n        - Edge condition: fraying, chipping, wear\r\n        - Print/image quality: clear, faded, scratched\r\n        - Protective elements: lamination, dust jacket, shrink wrap\r\n        \r\n        Back Cover:\r\n        - Similar assessment as front cover\r\n        - Spine attachment condition\r\n        - Flap condition (if applicable)\r\n        \r\n        Spine:\r\n        - Structural integrity: intact, cracked, broken, detached\r\n        - Title/text legibility\r\n        - Fading or wear patterns\r\n        - Binding visibility and condition\r\n        \r\n        BINDING EXAMINATION:\r\n        - Binding type: sewn, glued, stapled, spiral\r\n        - Binding integrity: tight, loose, broken, separating\r\n        - Hinge condition: flexible, stiff, broken\r\n        - Thread/glue condition (if visible)\r\n        \r\n        PAGE EXAMINATION (if visible):\r\n        - Page color: white, cream, yellowed, browned, foxed\r\n        - Page brittleness indicators: edges, handling marks\r\n        - Stains or spots: location, type, extent\r\n        - Tears or missing sections\r\n        - Text legibility: clear, faded, smudged\r\n        - Page attachment to binding\r\n        \r\n        DAMAGE ASSESSMENT:\r\n        For each observed issue, rate severity:\r\n        - NONE: No damage present\r\n        - MINIMAL: Barely noticeable, no functional impact\r\n        - MINOR: Noticeable but not affecting usability\r\n        - MODERATE: Clearly visible, some functional impact\r\n        - MAJOR: Significant damage, substantial impact\r\n        - SEVERE: Extensive damage, major functional issues\r\n        - CRITICAL: Extreme deterioration, barely functional\r\n        \r\n        READABILITY IMPACT:\r\n        - Can all text be read clearly?\r\n        - Are there any areas where text is obscured?\r\n        - How does damage affect book usability?\r\n        \r\n        {% endfor %}\r\n        \r\n        Document all observations in 'physicalObservations' array, one entry per image.\r\n\r\n        ---\r\n\r\n        STEP 2: CONDITION SYNTHESIS & CLASSIFICATION\r\n        \r\n        Synthesize observations to determine overall condition:\r\n        \r\n        CONDITION CLASSIFICATION CRITERIA:\r\n        \r\n        BARU (Brand New):\r\n        - No visible wear or damage whatsoever\r\n        - May have original shrink wrap\r\n        - Pristine preservation condition\r\n        - Perfect structural integrity\r\n        → Use this ONLY if book appears completely unused\r\n        \r\n        SANGAT_BAIK (Excellent):\r\n        - Almost no signs of wear\r\n        - No shrink wrap but looks almost new\r\n        - All pages clean and intact\r\n        - Cover in great shape, no defects\r\n        - Minimal to no discoloration\r\n        → Use for books in near-mint condition\r\n        \r\n        BAIK (Very Good):\r\n        - Minor wear but no major defects\r\n        - Pages clean and intact\r\n        - Cover shows slight use\r\n        - All text clearly legible\r\n        - Minimal age-related changes\r\n        → Use for well-maintained books with light use\r\n        \r\n        CUKUP_BAIK (Good):\r\n        - Noticeable wear and defects\r\n        - Text perfectly readable\r\n        - Book fully intact\r\n        - Cover colors may be faded\r\n        - Pages may be yellowed but prints clear\r\n        → Use for books showing normal aging and use\r\n        \r\n        DITERIMA (Acceptable/Poor):\r\n        - Heavy damage present\r\n        - Significant wear, tears, or water/mold damage\r\n        - Some text may be missing or illegible\r\n        - Metadata still inferable\r\n        - Structural integrity compromised but functional\r\n        → Use for damaged books still containing useful information\r\n        \r\n        BURUK (Bad):\r\n        - Extremely poor condition\r\n        - Extensive deterioration\r\n        - Pages torn, missing, or severely damaged\r\n        - Text barely readable or illegible\r\n        - Metadata cannot be reliably inferred\r\n        - Requires immediate conservation or may be unsalvageable\r\n        → Use only for severely damaged books\r\n        \r\n        ANALYSIS REQUIRED:\r\n        - What is the overall condition across all images?\r\n        - What are the most significant condition factors?\r\n        - How does the damage pattern compare to enum criteria?\r\n        - Are there any edge cases or borderline situations?\r\n        - What preservation urgency does this condition suggest?\r\n        \r\n        Document in 'conditionAnalysis' field.\r\n\r\n        ---\r\n\r\n        STEP 3: PRINT TYPE DETERMINATION\r\n        \r\n        Determine the book's print type based on construction and production quality:\r\n        \r\n        PRINT TYPE CLASSIFICATION CRITERIA:\r\n        \r\n        HARDCOVER:\r\n        Indicators:\r\n        - Rigid cover made of thick board/cardboard\r\n        - Cover wrapped in cloth, paper, or synthetic material\r\n        - Professional binding (sewn or high-quality perfect binding)\r\n        - Spine typically reinforced\r\n        - May have dust jacket\r\n        - Higher production quality\r\n        - Substantial weight and feel\r\n        → Look for: rigidity, professional binding, quality materials\r\n        \r\n        PAPERBACK:\r\n        Indicators:\r\n        - Flexible cover made of card stock or thick paper\r\n        - Perfect binding (glued spine) or saddle stitch\r\n        - Lighter weight than hardcover\r\n        - Cover may be glossy or matte finish\r\n        - Professional commercial printing\r\n        - Mass-market or trade paperback quality\r\n        - Spine shows paper/card construction\r\n        → Look for: flexibility, commercial quality, standard binding\r\n        \r\n        FOTOKOPI (Photocopy/Reproduction):\r\n        Indicators:\r\n        - Lower print quality (uneven ink density, copy artifacts)\r\n        - Simple binding (stapled, comb-bound, thermal-bound)\r\n        - Basic paper quality (often plain copier paper)\r\n        - No professional cover design\r\n        - May show copy machine artifacts (edge marks, alignment issues)\r\n        - Binding typically minimal or improvised\r\n        - Text may show characteristic photocopy appearance\r\n        → Look for: copy artifacts, simple binding, basic materials\r\n        \r\n        AMBIGUOUS CASES:\r\n        - High-quality print-on-demand: May look like paperback\r\n        - Professionally reproduced academic works: Check for binding quality\r\n        - Damaged hardcovers: Original structure may be visible\r\n        - Rebound books: Check for signs of rebinding\r\n        \r\n        ANALYSIS REQUIRED:\r\n        - What cover material do you observe?\r\n        - What type of binding is present?\r\n        - What production quality indicators are visible?\r\n        - Does it match commercial printing standards?\r\n        - Are there photocopy or reproduction indicators?\r\n        \r\n        Document in 'printTypeAnalysis' field.\r\n\r\n        ---\r\n\r\n        STEP 4: FINAL CLASSIFICATION\r\n        \r\n        Make final classification decisions:\r\n        \r\n        CONDITION:\r\n        Based on your conditionAnalysis, select the most appropriate BookCondition enum:\r\n        - Review all observed damage\r\n        - Compare with condition criteria\r\n        - Consider preservation urgency\r\n        - Make final classification\r\n        → Must align with your documented reasoning\r\n        \r\n        PRINTTYPE:\r\n        Based on your printTypeAnalysis, select the most appropriate BookPrintType enum:\r\n        - Review cover and binding observations\r\n        - Compare with print type criteria\r\n        - Consider production quality indicators\r\n        - Make final classification\r\n        → Must align with your documented reasoning\r\n\r\n        ---\r\n\r\n        CRITICAL GUIDELINES:\r\n        \r\n        ✓ Examine each image systematically and thoroughly\r\n        ✓ Document all physical observations objectively\r\n        ✓ Rate severity accurately using the provided scale\r\n        ✓ Assess readability impact for preservation planning\r\n        ✓ Compare observations across all images for consistency\r\n        ✓ Use condition criteria strictly - don't over- or under-classify\r\n        ✓ Distinguish between age-related wear and damage\r\n        ✓ Consider both aesthetic and functional condition\r\n        ✓ For print type, look for specific construction indicators\r\n        ✓ Don't confuse poor condition with photocopy indicators\r\n        ✓ Be conservative in classification when borderline\r\n        ✓ Document reasoning clearly for quality control\r\n        ✓ The final JSON may include comments explaining your reasoning\r\n        ✓ It's ok if the JSON isn't fully valid initially, we will clean it afterwards\r\n        ✓ Write a codeblock ONLY for the final JSON data containing your analysis\r\n        \r\n        {{ ctx.output_format }}\r\n\r\n        {{ _.role(\"user\") }}\r\n        \r\n        BOOK IMAGES FOR CONDITION ASSESSMENT:\r\n        {% for image in MultiImages %}\r\n        Image {{loop.index}} of {{total_images}}: {{image}}\r\n        {% endfor %}\r\n        \r\n        Please assess Book ID {{bookId}} following the 4-step workflow above. Conduct a thorough physical examination, synthesize your observations into condition and print type analyses, then provide final classifications with clear reasoning.\r\n        \r\n        Remember: Your assessment will guide preservation decisions. Be thorough, objective, and precise.\r\n    \"#\r\n}",
    "bookContentHints.baml": "class BookContentHints {\r\n    // Chain-of-thought reasoning fields\r\n    extractedTextSnippets string[] @description(#\"\r\n        List all relevant text snippets found in the images and notes that might contain blurb text, descriptions, or content-related information. Include quotes from back cover, inside flaps, book descriptions, or any promotional text. Each snippet should be a direct quote from the source material.\r\n    \"#)\r\n    \r\n    nerCandidates string[] @description(#\"\r\n        List all potential named entities identified from the text snippets. Include names of people, places, organizations, historical figures, dates, events, etc. Be comprehensive in this initial extraction phase.\r\n    \"#)\r\n    \r\n    contentClues string[] @description(#\"\r\n        Before making final decisions, list out observable clues about the book's nature:\r\n        - Keywords or phrases suggesting fiction vs non-fiction\r\n        - Narrative style indicators (e.g., \"once upon a time\", \"this study examines\")\r\n        - Presence of character names vs. real people/events\r\n        - Academic or scholarly language vs. narrative prose\r\n        - Any genre-specific terminology or themes\r\n    \"#)\r\n    \r\n    // Final analysis fields\r\n    bookBlurbText string? @description(#\"\r\n        The finalized blurb text or book description extracted from the identified text snippets. Synthesize the most relevant descriptive text about the book's content. If multiple description texts are found, combine them coherently. If not available, state \"no blurb text available\"\r\n    \"#)\r\n    \r\n    bookNERData string[] @description(#\"\r\n        Final curated list of named entities extracted from the blurb text and other relevant content. Remove duplicates and false positives from the nerCandidates. Entities should be organized and verified. Include:\r\n        - Person names (authors, characters, historical figures)\r\n        - Place names (cities, countries, regions)\r\n        - Organizations (companies, institutions)\r\n        - Temporal references (dates, time periods, events)\r\n    \"#)\r\n    \r\n    fictionAnalysis string @description(#\"\r\n        Detailed reasoning for determining whether this book is fiction or non-fiction. Reference specific clues from contentClues and explain your logical reasoning process. Consider:\r\n        - Is this telling a fabricated story or presenting factual information?\r\n        - Does it feature invented characters or real people/events?\r\n        - What is the author's intent based on available evidence?\r\n    \"#)\r\n    \r\n    isFiction bool @description(\"Final determination: true if fiction, false if non-fiction. This should align with the fictionAnalysis reasoning.\")\r\n    \r\n    genreAnalysis string @description(#\"\r\n        Detailed reasoning for genre classification. Explain what specific elements, themes, keywords, or patterns led you to each genre determination. Reference the contentClues and other extracted information. Consider multiple genre possibilities and explain why certain genres fit better than others.\r\n    \"#)\r\n    \r\n    bookGenre string[] @description(#\"\r\n        Final genre classification(s) for the book. Can include multiple genres if the book spans categories. Common genres include but not limited to:\r\n        Fiction: Literary Fiction, Science Fiction, Fantasy, Mystery, Thriller, Romance, Historical Fiction, Horror, Adventure\r\n        Non-fiction: Biography, Autobiography, History, Science, Philosophy, Self-help, Travel, Memoir, Essay, Academic/Textbook\r\n        Specialized: Poetry, Drama, Graphic Novel, Children's Literature, Young Adult\r\n    \"#)\r\n    \r\n    bookContextHints string? @description(#\"\r\n        Synthesized contextual information that enriches understanding of the book. Include:\r\n        - Historical or cultural context referenced in the content\r\n        - Thematic elements and their significance\r\n        - Potential target audience or reading level\r\n        - Literary or intellectual traditions it might belong to\r\n        - Any unique characteristics or notable aspects\r\n        Base this only on evidence from the analyzed material, avoid speculation.\r\n    \"#)\r\n}\r\n\r\nfunction GetBookContentHints(MultiImages: image[], bookId: string, RawVisualNote: string) -> BookContentHints {\r\n    client \"Gemini20FlashLite\"\r\n    prompt #\"\r\n        You are an expert literary analyst and librarian specializing in content classification and metadata extraction. Your role is to perform a thorough, step-by-step analysis of book content to extract meaningful insights about its nature, themes, and classification.\r\n\r\n        CONTEXT:\r\n        The field team has collected photos of a book (ID: {{bookId}}). A previous team member has documented important visual and textual details from these images. Your task is to analyze this information systematically using a chain-of-thought approach to extract content hints, classify the book, and identify key entities and themes.\r\n\r\n        ANALYTICAL WORKFLOW:\r\n        You must follow this step-by-step reasoning process. Think carefully through each stage:\r\n\r\n        {% set total_images = MultiImages|length %}\r\n        \r\n        STEP 1: TEXT EXTRACTION & COMPILATION\r\n        First, examine all available sources to extract text snippets that describe the book's content:\r\n        \r\n        {% if total_images > 0 %}\r\n        - Analyze ALL {{total_images}} image(s) provided\r\n        - Look for blurb text (often on back cover or inside flaps)\r\n        - Identify promotional descriptions or summaries\r\n        - Note any review quotes or endorsements\r\n        {% endif %}\r\n        \r\n        - Review the detailed notes from the previous team member: \r\n        {{RawVisualNote}}\r\n        \r\n        Extract and list ALL relevant text snippets in the 'extractedTextSnippets' field. Be thorough.\r\n\r\n        ---\r\n\r\n        STEP 2: NAMED ENTITY RECOGNITION (NER)\r\n        Based on the text snippets you extracted, identify ALL potential named entities:\r\n        - Scan for proper nouns (capitalized words that could be names)\r\n        - Identify person names (could be authors, characters, historical figures)\r\n        - Identify place names (cities, countries, regions, landmarks)\r\n        - Identify organizations (companies, institutions, groups)\r\n        - Identify temporal references (dates, years, time periods, historical events)\r\n        \r\n        List all candidates in 'nerCandidates' - it's better to be over-inclusive at this stage.\r\n\r\n        ---\r\n\r\n        STEP 3: CONTENT ANALYSIS & CLUE GATHERING\r\n        Examine the extracted text for clues about the book's nature:\r\n        \r\n        {% if total_images > 1 %}\r\n        Consider patterns across the {{total_images}} images:\r\n        {% endif %}\r\n        \r\n        - What type of language is used? (narrative, academic, poetic, technical, etc.)\r\n        - Are there indicators of fictional storytelling vs. factual reporting?\r\n        - What themes or subjects are explicitly mentioned?\r\n        - What genre-specific keywords appear? (e.g., \"mystery\", \"history of\", \"guide to\")\r\n        - Are there character names vs. historical/real person names?\r\n        - Does it describe a plot/story or explain factual information?\r\n        \r\n        Document your observations in 'contentClues'.\r\n\r\n        ---\r\n\r\n        STEP 4: FICTION VS NON-FICTION DETERMINATION\r\n        Now, synthesize your observations to determine if this is fiction or non-fiction:\r\n        \r\n        Consider:\r\n        - Does it present imagined events and characters, or real-world information?\r\n        - Is the primary purpose to tell a story or to inform/educate?\r\n        - What does the language style suggest?\r\n        - What do the named entities tell you? (fictional characters vs. historical figures)\r\n        \r\n        Write your detailed reasoning in 'fictionAnalysis', then set 'isFiction' (true/false).\r\n\r\n        ---\r\n\r\n        STEP 5: GENRE CLASSIFICATION\r\n        Based on all the evidence gathered, classify the book into appropriate genre(s):\r\n        \r\n        Think through:\r\n        - What are the primary themes and subject matter?\r\n        - What genre conventions or markers are present?\r\n        - Does it fit into multiple genres (e.g., historical fiction, science fiction mystery)?\r\n        - What specific textual evidence supports each genre choice?\r\n        \r\n        Document your reasoning in 'genreAnalysis', then list the genre(s) in 'bookGenre'.\r\n\r\n        ---\r\n\r\n        STEP 6: FINALIZATION & SYNTHESIS\r\n        Finally, compile your final outputs:\r\n        \r\n        - Synthesize the best blurb text from your extracted snippets ('bookBlurbText')\r\n        - Curate and deduplicate the NER candidates into a final list ('bookNERData')\r\n        - Compile contextual insights about the book's significance ('bookContextHints')\r\n\r\n        ---\r\n\r\n        IMPORTANT GUIDELINES:\r\n        - Base ALL conclusions on observable evidence from the images and notes\r\n        - When uncertain, acknowledge it - don't fabricate information\r\n        - If a field cannot be determined, explain why in your reasoning\r\n        - Think step-by-step, showing your work in the reasoning fields\r\n        - The final JSON may include comments with your reasoning inline\r\n        - It's ok if this isn't fully valid JSON initially, we will clean it afterwards, but please write a codeblock ONLY for the final JSON data containing only your analysis.\r\n\r\n        {{ ctx.output_format }}\r\n\r\n        {{ _.role(\"user\") }}\r\n        \r\n        {% for image in MultiImages %}\r\n        Image {{loop.index}} of {{total_images}}: {{image}}\r\n        {% endfor %}\r\n        \r\n        Field Team Notes:\r\n        ---\r\n        {{RawVisualNote}}\r\n        ---\r\n\r\n        Please analyze book ID {{bookId}} following the step-by-step workflow above. Show your reasoning at each stage, then provide the final structured output.\r\n    \"#\r\n}",
    "bookMainData.baml": "class BookTitle {\r\n    title_in_origin_script string @description(#\"\r\n        The title of the book in its original script. Aims for accuracy in the spelling, diacritics, and the use of special characters. If the title is in a non-Latin script (e.g., Chinese, Arabic, Cyrillic), please provide the title in that script as is.\r\n    \"#)\r\n    title_in_latin_script string @description(#\"\r\n        The title of the book transliterated into the Latin script. This is especially important for titles originally in non-Latin scripts (e.g., Chinese, Arabic, Cyrillic). Do not translate the title; instead, provide a phonetic representation using Latin characters. Make sure that you transliterate special characters and diacritics, so that the final title is ASCII-safe string.\r\n    \"#)\r\n    title_in_indonesian string @description(#\"\r\n        The title of the book translated into Indonesian. If the book is originally in Indonesian, please input the title as is.\r\n    \"#)\r\n}\r\n\r\nclass BookAuthor {\r\n    author_in_origin_script string @description(\"Author name in original script/language\")\r\n    author_in_latin_script string @description(#\"\r\n    Author name transliterated into Latin script. Make sure that you transliterate special characters and diacritics, so that the final title is ASCII-safe string. In the case that the author name is already in Latin script, please input the name as is.\r\n    \"#)\r\n}\r\n\r\nclass BookTranslator {\r\n    translators_in_origin_script string @description(\"The translator name in original script/language\")\r\n    translators_in_latin_script string @description(#\"\r\n    Translator name transliterated into Latin script. Make sure that you transliterate special characters and diacritics, so that the final title is ASCII-safe string. In the case that the translator name is already in Latin script, please input the name as is.\r\n    \"#)\r\n}\r\n\r\nclass TextExtractionEvidence {\r\n    imageNumber int @description(\"The index number of the image this evidence comes from\")\r\n    location string @description(\"Where on the page this text was found (e.g., 'front cover - top', 'spine', 'back cover - bottom', 'colophon page - center')\")\r\n    extractedText string @description(\"The exact text as it appears, in its original script\")\r\n    textType string @description(\"What this text likely represents (e.g., 'title', 'author name', 'publisher', 'ISBN', 'publication year', 'translator', 'edition info')\")\r\n    scriptIdentified string @description(\"The script system used (e.g., 'Latin', 'Cyrillic', 'Arabic', 'Chinese', 'Japanese', 'Korean', 'Devanagari')\")\r\n    confidence string @description(\"Your confidence in this extraction: 'high', 'medium', or 'low'\")\r\n}\r\n\r\nclass DataComparison {\r\n    fieldName string @description(\"The bibliographic field being compared (e.g., 'title', 'author', 'ISBN')\")\r\n    fromImages string @description(\"What you extracted from the images\")\r\n    fromNotes string @description(\"What the previous team member noted\")\r\n    agreement bool @description(\"Whether the two sources agree\")\r\n    reasoning string @description(#\"\r\n        If there's disagreement, explain which source is more reliable and why. Consider factors like:\r\n        - Image quality and clarity\r\n        - Completeness of information\r\n        - Consistency across multiple image locations\r\n        - Script/language accuracy\r\n    \"#)\r\n    finalDecision string @description(\"The value you've decided to use in the final output\")\r\n}\r\n\r\nclass BookMainData {\r\n    // Chain-of-thought reasoning fields\r\n    extractionEvidence TextExtractionEvidence[] @description(#\"\r\n        Document ALL text extractions from the images. For each piece of text you can read from any image:\r\n        - Note which image it comes from\r\n        - Specify the location on that page\r\n        - Record the exact text in its original script\r\n        - Identify what type of information it likely represents\r\n        - Identify the script system\r\n        - Rate your confidence in the extraction\r\n    \"#)\r\n    \r\n    languageScriptAnalysis string @description(#\"\r\n        Analyze the linguistic and script characteristics observed:\r\n        - What language(s) appear in the book's text?\r\n        - What script system(s) are used for writing?\r\n        - Are there multiple languages (e.g., original + translation)?\r\n        - How did you determine the language(s) and script(s)?\r\n        - Note any special characters, diacritics, or writing system features\r\n    \"#)\r\n    \r\n    dataComparisons DataComparison[] @description(#\"\r\n        Compare your image-based extractions with the team member's notes field by field.\r\n        For each bibliographic field (title, author, ISBN, year, etc.):\r\n        - State what you found in images\r\n        - State what the notes say\r\n        - Indicate if they agree or disagree\r\n        - If they disagree, provide detailed reasoning about which is more accurate\r\n        - State your final decision\r\n    \"#)\r\n    \r\n    transliterationReasoning string @description(#\"\r\n        For non-Latin scripts, explain your transliteration approach:\r\n        - What transliteration system are you using? (e.g., Pinyin for Chinese, Hepburn for Japanese)\r\n        - How are you handling special characters and diacritics?\r\n        - What challenges did you encounter in creating ASCII-safe versions?\r\n        - Document any ambiguous cases and how you resolved them\r\n    \"#)\r\n    \r\n    // Final extracted fields\r\n    title BookTitle @description(\"Book title information, in original script, latin script, and indonesian translation. Based on your analysis and comparisons above.\")\r\n    \r\n    language string[] @description(#\"\r\n        The language(s) that exists within the given book's data. Based on your languageScriptAnalysis.\r\n        Examples: [\"English\"], [\"Indonesian\"], [\"Russian\", \"English\"], [\"Japanese\"]\r\n    \"#)\r\n    \r\n    script string[] @description(#\"\r\n        The script(s) that exists within the given book's data. Based on your languageScriptAnalysis.\r\n        Examples: [\"Latin\"], [\"Cyrillic\"], [\"Arabic\"], [\"Chinese (Simplified)\"], [\"Devanagari\"], [\"Latin\", \"Cyrillic\"]\r\n    \"#)\r\n    \r\n    authors BookAuthor[] @description(\"List of book authors. Each author should have both original script and transliterated versions based on your extraction evidence.\")\r\n    \r\n    translator BookTranslator[]? @description(\"List of translators if applicable. Only include if translation information is present in the evidence.\")\r\n    \r\n    isbn_13 string? @description(\"13-digit ISBN if visible and/or present. Verify format: should be exactly 13 digits, possibly with hyphens.\")\r\n    \r\n    isbn_10 string? @description(\"10-digit ISBN if visible and/or present. Verify format: should be exactly 10 digits, possibly with hyphens.\")\r\n    \r\n    published_year int? @description(\"The year the book was published, if visible and/or present. Should be a 4-digit year.\")\r\n    \r\n    confidence float @description(#\"\r\n        Overall confidence level of extraction (0.0-1.0). Consider:\r\n        - Image quality and readability\r\n        - Agreement between images and notes\r\n        - Completeness of information\r\n        - Clarity of critical fields (title, author)\r\n        - Any ambiguities or uncertainties in the process\r\n    \"#)\r\n}\r\n\r\nfunction GetBookMainData(MultiImages: image[], bookId: string, RawVisualNote: string) -> BookMainData {\r\n    client \"Gemini20FlashLite\"\r\n    prompt #\"\r\n        You are an expert librarian and archivist specializing in multilingual bibliographic data extraction. Your role in this national library cataloguing project is to perform precise, systematic extraction of bibliographic metadata from book photographs, ensuring accuracy across different scripts and languages.\r\n\r\n        CONTEXT:\r\n        Book ID: {{bookId}}\r\n        You have received {{MultiImages|length}} image(s) of this book, showing various parts including front cover, back cover, spine, colophon page, and potentially other relevant pages. A previous team member has provided detailed notes about the visual content. All images are guaranteed to be of the same book.\r\n\r\n        YOUR MISSION:\r\n        Extract comprehensive bibliographic data through a systematic, evidence-based chain-of-thought process. You must document your reasoning at each step to ensure accuracy and enable verification.\r\n\r\n        \r\n        ANALYTICAL WORKFLOW - FOLLOW THESE STEPS SEQUENTIALLY:\r\n\r\n        {% set total_images = MultiImages|length %}\r\n        \r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 1: COMPREHENSIVE TEXT EXTRACTION FROM ALL IMAGES                        ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        Systematically examine each of the {{total_images}} image(s):\r\n        \r\n        {% for image in MultiImages %}\r\n        IMAGE {{loop.index}} of {{total_images}}:\r\n        For this image, extract ALL readable text regardless of script or language:\r\n        - Identify the page type (front cover, back cover, spine, colophon, etc.)\r\n        - Locate and transcribe each text element with its position\r\n        - Record text EXACTLY as it appears in its original script\r\n        - Determine what each text element likely represents:\r\n          * Title (main title, subtitle)\r\n          * Author name(s)\r\n          * Translator name(s)\r\n          * Publisher name\r\n          * Publication year\r\n          * ISBN numbers (10-digit or 13-digit)\r\n          * Edition information\r\n          * Series information\r\n        - Identify the script system used (Latin, Cyrillic, Arabic, Chinese, Japanese, Korean, Devanagari, etc.)\r\n        - Rate your confidence (high/medium/low) based on image quality and text clarity\r\n        \r\n        {% endfor %}\r\n        \r\n        Document all findings in the 'extractionEvidence' array. Be thorough and systematic.\r\n\r\n        ---\r\n\r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 2: LANGUAGE AND SCRIPT ANALYSIS                                         ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        Based on the text you extracted, analyze linguistic characteristics:\r\n        \r\n        LANGUAGE IDENTIFICATION:\r\n        - What language(s) is the book written in?\r\n        - Are there multiple languages present? (e.g., bilingual edition, translation)\r\n        - What textual clues indicate the language? (vocabulary, grammar, character sets)\r\n        \r\n        SCRIPT IDENTIFICATION:\r\n        - What writing system(s) are used?\r\n        - Are there mixed scripts? (e.g., Latin with Japanese, Arabic with English)\r\n        - Note any special characters, diacritics, or unique script features\r\n        \r\n        Document your analysis in 'languageScriptAnalysis' with clear reasoning.\r\n\r\n        ---\r\n\r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 3: CROSS-VALIDATION WITH TEAM MEMBER NOTES                              ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        The previous team member provided these notes:\r\n        ---\r\n        {{RawVisualNote}}\r\n        ---\r\n        \r\n        Now perform field-by-field comparison:\r\n        \r\n        For EACH bibliographic field, document in 'dataComparisons':\r\n        \r\n        TITLE:\r\n        - What title did you extract from images?\r\n        - What title is in the notes?\r\n        - Do they match? If not, which is more accurate and why?\r\n        \r\n        AUTHOR(S):\r\n        - What author name(s) did you find?\r\n        - What does the notes say?\r\n        - Evaluate discrepancies considering: name spelling, script variations, completeness\r\n        \r\n        ISBN:\r\n        - Did you find ISBN-13 or ISBN-10?\r\n        - Does it match the notes?\r\n        - Verify the format is correct (13 or 10 digits)\r\n        \r\n        PUBLICATION YEAR:\r\n        - What year did you extract?\r\n        - What year is in the notes?\r\n        - Which source is more reliable?\r\n        \r\n        PUBLISHER:\r\n        - Publisher information from images vs. notes\r\n        - Consistency check\r\n        \r\n        TRANSLATOR (if applicable):\r\n        - Is this a translation?\r\n        - Who is listed as translator?\r\n        - Cross-check sources\r\n        \r\n        For EACH comparison, provide:\r\n        - Your finding\r\n        - Notes finding\r\n        - Agreement (true/false)\r\n        - Reasoning (especially if disagreement)\r\n        - Final decision on which value to use\r\n\r\n        ---\r\n\r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 4: TRANSLITERATION STRATEGY (For Non-Latin Scripts)                     ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        {% if total_images > 0 %}\r\n        If the book uses non-Latin scripts, document your transliteration approach:\r\n        {% endif %}\r\n        \r\n        TRANSLITERATION SYSTEM:\r\n        - For Chinese: Use Pinyin romanization\r\n        - For Japanese: Use Hepburn romanization\r\n        - For Korean: Use Revised Romanization of Korean\r\n        - For Russian/Cyrillic: Use BGN/PCGN romanization or ISO 9\r\n        - For Arabic: Use ALA-LC romanization\r\n        - For other scripts: Specify the system used\r\n        \r\n        ASCII SAFETY:\r\n        - How are you converting special characters?\r\n        - How are diacritics being handled? (e.g., ü → u, ñ → n)\r\n        - What about special letters? (e.g., ø → o, ß → ss)\r\n        \r\n        AMBIGUITY RESOLUTION:\r\n        - Document any challenging cases\r\n        - Explain your decision-making process\r\n        - Note alternative transliterations considered\r\n        \r\n        Record in 'transliterationReasoning' field.\r\n\r\n        ---\r\n\r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 5: CONFIDENCE ASSESSMENT                                                ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        Evaluate your overall confidence (0.0 to 1.0):\r\n        \r\n        Consider these factors:\r\n        - Image quality: Are all images clear and readable? (+)\r\n        - Text legibility: Can you read all critical information clearly? (+)\r\n        - Agreement: Do images and notes agree? (+)\r\n        - Completeness: Is all bibliographic data present? (+)\r\n        - Ambiguity: Are there uncertain or unclear elements? (-)\r\n        - Script complexity: Are non-Latin scripts clear and identifiable? (+/-)\r\n        - Discrepancies: Are there conflicts between sources? (-)\r\n        \r\n        Confidence scale:\r\n        - 0.9-1.0: Excellent quality, complete data, high certainty\r\n        - 0.7-0.89: Good quality, mostly complete, minor uncertainties\r\n        - 0.5-0.69: Moderate quality, some missing data, notable uncertainties\r\n        - 0.3-0.49: Poor quality, incomplete data, significant uncertainties\r\n        - 0.0-0.29: Very poor quality, major data gaps, high uncertainty\r\n\r\n        ---\r\n\r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 6: FINAL DATA COMPILATION                                               ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        Now compile your final bibliographic data:\r\n        \r\n        TITLE (BookTitle object):\r\n        - title_in_origin_script: Exact title in original script\r\n        - title_in_latin_script: Transliterated title (ASCII-safe)\r\n        - title_in_indonesian: Indonesian translation (or original if already Indonesian)\r\n        \r\n        AUTHORS (BookAuthor array):\r\n        - For each author: original script + Latin transliteration\r\n        \r\n        TRANSLATORS (BookTranslator array, if applicable):\r\n        - For each translator: original script + Latin transliteration\r\n        - Only include if translation is confirmed\r\n        \r\n        LANGUAGE array: List all languages present\r\n        SCRIPT array: List all writing systems used\r\n        \r\n        ISBN_13: 13-digit ISBN if present (format: XXX-X-XXX-XXXXX-X or XXXXXXXXXXXXX)\r\n        ISBN_10: 10-digit ISBN if present (format: X-XXX-XXXXX-X or XXXXXXXXXX)\r\n        \r\n        PUBLISHED_YEAR: 4-digit year (YYYY format)\r\n        \r\n        CONFIDENCE: Your calculated confidence score (0.0-1.0)\r\n\r\n        ---\r\n\r\n        CRITICAL GUIDELINES:\r\n        ═══════════════════════════════════════════════════════════════════════════════\r\n        \r\n        ✓ Extract text EXACTLY as it appears - preserve original script accuracy\r\n        ✓ Document your reasoning at every step\r\n        ✓ When sources conflict, explain which is more reliable and why\r\n        ✓ For non-Latin scripts, follow standard transliteration systems\r\n        ✓ Ensure ASCII safety in Latin transliterations\r\n        ✓ Be honest about uncertainties - don't fabricate data\r\n        ✓ Cross-validate information across multiple image locations when possible\r\n        ✓ The final JSON may include comments explaining your reasoning\r\n        ✓ It's ok if the JSON isn't fully valid initially, we will clean it afterwards\r\n        ✓ Write a codeblock ONLY for the final JSON data containing your analysis\r\n        \r\n        ═══════════════════════════════════════════════════════════════════════════════\r\n\r\n        {{ ctx.output_format }}\r\n\r\n        {{ _.role(\"user\") }}\r\n        \r\n        BOOK IMAGES:\r\n        {% for image in MultiImages %}\r\n        Image {{loop.index}} of {{total_images}}: {{image}}\r\n        {% endfor %}\r\n        \r\n        TEAM MEMBER NOTES:\r\n        ---\r\n        {{RawVisualNote}}\r\n        ---\r\n        \r\n        Please analyze Book ID {{bookId}} following the 6-step workflow above. Document your reasoning thoroughly, then provide the final structured bibliographic data.\r\n    \"#\r\n}",
    "bookPublisherData.baml": "class PublisherName {\r\n    original_script string @description(\"Publisher name in original script/language\")\r\n    romanized string? @description(\"Romanized version of publisher name if applicable\")\r\n    english_translation string? @description(\"English translation of publisher name if applicable\")\r\n    indonesian_translation string? @description(\"Indonesian translation of publisher name if applicable\")\r\n}\r\n\r\nclass PublisherLocation {\r\n    original_script string @description(\"Publisher location in original script/language\")\r\n    romanized string? @description(\"Romanized version of publisher location if applicable\")\r\n    english_translation string? @description(\"English translation of publisher location\")\r\n    indonesian_translation string? @description(\"Indonesian translation of publisher location\")\r\n    country string @description(\"Country name in English\")\r\n}\r\n\r\nclass Editor {\r\n    original_script string @description(\"Editor name in original script/language\")\r\n    romanized string? @description(\"Romanized version of editor name if applicable\")\r\n}\r\n\r\nclass DistributorName {\r\n    original_script string @description(\"Distributor name in original script/language\")\r\n    romanized string? @description(\"Romanized version of distributor name if applicable\")\r\n    english_translation string? @description(\"English translation of distributor name\")\r\n    indonesian_translation string? @description(\"Indonesian translation of distributor name\")\r\n}\r\n\r\nclass DistributorLocation {\r\n    original_script string @description(\"Distributor location in original script/language\")\r\n    romanized string? @description(\"Romanized version of distributor location if applicable\")\r\n    english_translation string? @description(\"English translation of distributor location\")\r\n    indonesian_translation string? @description(\"Indonesian translation of distributor location\")\r\n    country string @description(\"Country name in English\")\r\n}\r\n\r\nclass PublisherTextEvidence {\r\n    imageNumber int @description(\"The index number of the image this evidence comes from\")\r\n    pageType string @description(\"Type of page where found (e.g., 'colophon page', 'back cover', 'front cover', 'copyright page')\")\r\n    location string @description(\"Specific location on the page (e.g., 'bottom center', 'inside front flap', 'verso')\")\r\n    extractedText string @description(\"The exact text as it appears, in its original script\")\r\n    textType string @description(\"What this text represents (e.g., 'publisher name', 'publisher address', 'editor name', 'distributor', 'printer', 'imprint')\")\r\n    scriptIdentified string @description(\"The script system used\")\r\n    confidencePublisher string @description(\"Extraction confidence: 'high', 'medium', or 'low'\")\r\n}\r\n\r\nclass PublisherDataComparison {\r\n    fieldName string @description(\"The field being compared (e.g., 'publisher_name', 'publisher_location', 'editor', 'distributor')\")\r\n    fromImages string @description(\"What you extracted from the images\")\r\n    fromNotes string @description(\"What the previous team member noted\")\r\n    agreement bool @description(\"Whether the two sources agree\")\r\n    reasoning string @description(#\"\r\n        If there's disagreement, explain which source is more reliable and why. Consider:\r\n        - Clarity and completeness in images\r\n        - Typical colophon page conventions\r\n        - Script/language accuracy\r\n        - Consistency across multiple locations\r\n    \"#)\r\n    finalDecision string @description(\"The value you've decided to use in the final output\")\r\n}\r\n\r\nclass RoleDistinction {\r\n    publisherIdentified bool @description(\"Whether publisher information was found\")\r\n    editorIdentified bool @description(\"Whether editor information was found\")\r\n    distributorIdentified bool @description(\"Whether distributor information was found (distinct from publisher)\")\r\n    printerIdentified bool @description(\"Whether printer information was found (separate from publisher)\")\r\n    reasoning string @description(#\"\r\n        Explain how you distinguished between publisher, distributor, editor, and printer roles:\r\n        - Publishers typically appear with copyright symbols or publishing statements\r\n        - Distributors may be noted separately, especially for international books\r\n        - Editors are usually listed in smaller text or editorial credits\r\n        - Printers appear in production credits, often with 'printed by' language\r\n        Document any ambiguous cases and your reasoning.\r\n    \"#)\r\n}\r\n\r\nclass BookPubAndDistDetails {\r\n    // Chain-of-thought reasoning fields\r\n    extractionEvidence PublisherTextEvidence[] @description(#\"\r\n        Document ALL text extractions related to publishing information from the images.\r\n        Focus primarily on colophon page, but also check:\r\n        - Copyright page\r\n        - Back cover\r\n        - Inside covers\r\n        - Title page verso\r\n        For each piece of text, document location, content, type, and confidence.\r\n    \"#)\r\n    \r\n    roleDistinction RoleDistinction @description(#\"\r\n        Analyze and distinguish between different roles in the book's production:\r\n        - Who is the publisher? (primary entity responsible for the book)\r\n        - Who is the distributor? (if different from publisher)\r\n        - Who is the editor? (if listed)\r\n        - Who is the printer? (if separately identified)\r\n        Explain your reasoning for role assignments.\r\n    \"#)\r\n    \r\n    dataComparisons PublisherDataComparison[] @description(#\"\r\n        Compare your image-based extractions with the team member's notes field by field.\r\n        For each field (publisher name, location, editor, distributor):\r\n        - State what you found in images\r\n        - State what the notes say\r\n        - Indicate agreement or disagreement\r\n        - If they disagree, provide detailed reasoning\r\n        - State your final decision\r\n    \"#)\r\n    \r\n    transliterationStrategy string @description(#\"\r\n        For non-Latin scripts, document your transliteration and translation approach:\r\n        - What transliteration system are you using?\r\n        - How are you handling organizational names vs. personal names?\r\n        - What challenges did you encounter with place names?\r\n        - How are you ensuring ASCII safety for romanized versions?\r\n        - Document your translation strategy for English and Indonesian versions\r\n    \"#)\r\n    \r\n    geographicAnalysis string @description(#\"\r\n        Analyze the geographic information:\r\n        - How did you identify the country?\r\n        - Are there multiple locations mentioned? (e.g., publisher HQ vs. print location)\r\n        - How did you parse city, region, and country information?\r\n        - Any ambiguities in location identification?\r\n    \"#)\r\n    \r\n    // Final extracted fields\r\n    publisher_name PublisherName @description(\"Publisher name information in all relevant scripts and languages\")\r\n    \r\n    publisher_location PublisherLocation @description(\"Publisher location information in all relevant scripts and languages\")\r\n    \r\n    editor Editor? @description(\"Editor information if visible and confirmed. Only include if editor role is clearly identified.\")\r\n    \r\n    distributor_name DistributorName? @description(\"Distributor name information if different from publisher. Only include if distributor is explicitly mentioned as separate entity.\")\r\n    \r\n    distributor_location DistributorLocation? @description(\"Distributor location information if different from publisher location.\")\r\n    \r\n    confidence float @description(#\"\r\n        Overall confidence level of extraction (0.0-1.0). Consider:\r\n        - Clarity of colophon page or copyright page\r\n        - Agreement between images and notes\r\n        - Completeness of publisher information\r\n        - Ambiguity in role distinctions\r\n        - Quality of geographic information\r\n    \"#)\r\n    \r\n    image_count int @description(\"Number of images analyzed in this extraction\")\r\n}\r\n\r\nfunction GetBookPublisherData(MultiImages: image[], bookId: string, RawVisualNote: string) -> BookPubAndDistDetails {\r\n    client \"Gemini20FlashLite\"\r\n    prompt #\"\r\n        You are an expert librarian and publishing industry specialist with deep knowledge of book production, distribution, and colophon conventions across different countries and languages. Your role in this national library cataloguing project is to extract precise publisher and distributor information from book photographs.\r\n\r\n        CONTEXT:\r\n        Book ID: {{bookId}}\r\n        You have received {{MultiImages|length}} image(s) of this book. A previous team member has documented important textual and visual details. All images are guaranteed to be of the same book.\r\n\r\n        YOUR MISSION:\r\n        Extract comprehensive publisher and distributor data through a systematic, evidence-based chain-of-thought process. You must carefully distinguish between publishers, distributors, editors, and printers, as these roles are often confused.\r\n\r\n        ═══════════════════════════════════════════════════════════════════════════════\r\n        ANALYTICAL WORKFLOW - FOLLOW THESE STEPS SEQUENTIALLY:\r\n        ═══════════════════════════════════════════════════════════════════════════════\r\n\r\n        {% set total_images = MultiImages|length %}\r\n        \r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 1: COMPREHENSIVE TEXT EXTRACTION - PUBLISHING INFORMATION               ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        Systematically examine each of the {{total_images}} image(s) for publisher-related information:\r\n        \r\n        PRIMARY FOCUS: Colophon Page / Copyright Page\r\n        This is typically where publisher information appears. Look for:\r\n        - Copyright statements (©, Copyright, Hak Cipta)\r\n        - Publisher name and logo\r\n        - Publication date and place\r\n        - ISBN and cataloging data\r\n        - Printer information\r\n        - Distributor information\r\n        \r\n        SECONDARY LOCATIONS:\r\n        - Title page verso (back of title page)\r\n        - Back cover (publisher name/logo)\r\n        - Inside covers or flaps\r\n        - Spine (publisher imprint)\r\n        \r\n        {% for image in MultiImages %}\r\n        IMAGE {{loop.index}} of {{total_images}}:\r\n        For this image, extract ALL text related to publishing:\r\n        - Identify page type (colophon, copyright, back cover, etc.)\r\n        - Locate and transcribe publisher-related text with exact position\r\n        - Record text EXACTLY in its original script\r\n        - Classify each text element:\r\n          * Publisher name\r\n          * Publisher address/location\r\n          * Editor name (editorial credits)\r\n          * Distributor name (if separate from publisher)\r\n          * Distributor location\r\n          * Printer name (production credits)\r\n          * Copyright holder (often the publisher)\r\n          * Imprint information\r\n        - Identify script system used\r\n        - Rate confidence (high/medium/low)\r\n        \r\n        {% endfor %}\r\n        \r\n        Document all findings in 'extractionEvidence' array.\r\n\r\n        ---\r\n\r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 2: ROLE DISTINCTION - PUBLISHER vs DISTRIBUTOR vs EDITOR vs PRINTER     ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        Carefully distinguish between different entities:\r\n        \r\n        PUBLISHER:\r\n        - Primary entity responsible for the book's publication\r\n        - Usually appears with copyright statement\r\n        - Often has logo or imprint mark\r\n        - Typically listed first in credits\r\n        - May include phrases like \"Published by\", \"Diterbitkan oleh\", \"出版社\"\r\n        \r\n        DISTRIBUTOR:\r\n        - Handles distribution and sales (separate from publisher)\r\n        - More common in international or translated books\r\n        - Look for phrases like \"Distributed by\", \"Didistribusikan oleh\"\r\n        - May have different location from publisher\r\n        - Sometimes only appears on back cover\r\n        \r\n        EDITOR:\r\n        - Individual(s) who edited the content\r\n        - Usually smaller text or in editorial credits\r\n        - Look for \"Editor:\", \"Edited by\", \"Penyunting\"\r\n        - Personal name, not company name\r\n        \r\n        PRINTER:\r\n        - Company that physically printed the book\r\n        - Look for \"Printed by\", \"Dicetak oleh\", \"印刷\"\r\n        - Often includes print location\r\n        - May be same as or different from publisher\r\n        \r\n        Document your analysis in 'roleDistinction':\r\n        - Which entities did you identify?\r\n        - How did you distinguish between them?\r\n        - What textual/visual clues helped?\r\n        - Any ambiguous cases?\r\n\r\n        ---\r\n\r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 3: CROSS-VALIDATION WITH TEAM MEMBER NOTES                              ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        The previous team member provided these notes:\r\n        ---\r\n        {{RawVisualNote}}\r\n        ---\r\n        \r\n        Now perform field-by-field comparison:\r\n        \r\n        For EACH publishing-related field, document in 'dataComparisons':\r\n        \r\n        PUBLISHER NAME:\r\n        - What publisher name did you extract from images?\r\n        - What does the notes say?\r\n        - Do they match? Consider variations in spelling/transliteration\r\n        \r\n        PUBLISHER LOCATION:\r\n        - What location did you find?\r\n        - What location is in the notes?\r\n        - Check for city, region, country consistency\r\n        \r\n        EDITOR:\r\n        - Did you find editor information?\r\n        - Is it in the notes?\r\n        - Is the role clearly identified?\r\n        \r\n        DISTRIBUTOR:\r\n        - Is there a separate distributor?\r\n        - Does it match the notes?\r\n        - Is it truly different from the publisher?\r\n        \r\n        For EACH comparison, provide:\r\n        - Your finding\r\n        - Notes finding\r\n        - Agreement (true/false)\r\n        - Reasoning (especially if disagreement)\r\n        - Final decision\r\n\r\n        ---\r\n\r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 4: TRANSLITERATION & TRANSLATION STRATEGY                               ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        For publisher/distributor names and locations in non-Latin scripts:\r\n        \r\n        ORGANIZATIONAL NAME TRANSLITERATION:\r\n        - Use standard romanization for the language\r\n        - For well-known publishers, check for official romanization\r\n        - Handle company suffixes appropriately (Ltd., Co., Publishing House, etc.)\r\n        - Ensure ASCII safety (remove diacritics for romanized version)\r\n        \r\n        TRANSLATION STRATEGY:\r\n        - English translation: Translate descriptive parts, keep proper names\r\n          Example: \"上海人民出版社\" → \"Shanghai People's Publishing House\"\r\n        - Indonesian translation: Similar approach, localize to Indonesian\r\n        - Keep organizational structure indicators (PT, CV, Inc., etc.)\r\n        \r\n        PLACE NAME HANDLING:\r\n        - Use standard geographical name conventions\r\n        - City names: Use commonly accepted English/romanized forms\r\n        - Country identification: Use ISO standard English names\r\n        - Handle regional variations (e.g., Peking vs Beijing)\r\n        \r\n        Document in 'transliterationStrategy' field.\r\n\r\n        ---\r\n\r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 5: GEOGRAPHIC ANALYSIS                                                  ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        Analyze location information carefully:\r\n        \r\n        LOCATION PARSING:\r\n        - Identify city, state/province, country from addresses\r\n        - Handle abbreviated forms\r\n        - Distinguish publisher location from print location\r\n        - Note if multiple locations mentioned (e.g., HQ vs branch offices)\r\n        \r\n        COUNTRY IDENTIFICATION:\r\n        - Use context clues: language, script, address format\r\n        - Check postal codes or area codes if visible\r\n        - Consider publisher name conventions\r\n        - Use standard English country names in output\r\n        \r\n        AMBIGUITY HANDLING:\r\n        - What if location is unclear or abbreviated?\r\n        - What if publisher has offices in multiple countries?\r\n        - How do you handle historical place names?\r\n        \r\n        Document analysis in 'geographicAnalysis' field.\r\n\r\n        ---\r\n\r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 6: CONFIDENCE ASSESSMENT                                                ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        Evaluate overall confidence (0.0 to 1.0):\r\n        \r\n        Consider:\r\n        - Colophon page clarity: Is it clearly visible and readable? (+)\r\n        - Information completeness: All required fields present? (+)\r\n        - Agreement: Do images and notes agree? (+)\r\n        - Role clarity: Are publisher/distributor/editor clearly distinguished? (+)\r\n        - Location clarity: Is geographic information unambiguous? (+)\r\n        - Script legibility: Can you read all text clearly? (+)\r\n        - Ambiguities: Are there uncertain elements? (-)\r\n        \r\n        Confidence scale:\r\n        - 0.9-1.0: Excellent colophon, complete data, high certainty\r\n        - 0.7-0.89: Good information, mostly complete, minor uncertainties\r\n        - 0.5-0.69: Moderate quality, some gaps, notable ambiguities\r\n        - 0.3-0.49: Poor quality, incomplete, significant uncertainties\r\n        - 0.0-0.29: Very poor, major gaps, high uncertainty\r\n\r\n        ---\r\n\r\n        ╔═══════════════════════════════════════════════════════════════════════════════╗\r\n        ║ STEP 7: FINAL DATA COMPILATION                                               ║\r\n        ╚═══════════════════════════════════════════════════════════════════════════════╝\r\n        \r\n        Compile final publisher and distributor data:\r\n        \r\n        PUBLISHER_NAME (PublisherName object):\r\n        - original_script: Exact name in original script\r\n        - romanized: Romanized version (ASCII-safe)\r\n        - english_translation: English translation if applicable\r\n        - indonesian_translation: Indonesian translation if applicable\r\n        \r\n        PUBLISHER_LOCATION (PublisherLocation object):\r\n        - original_script: Exact location in original script\r\n        - romanized: Romanized version\r\n        - english_translation: English version\r\n        - indonesian_translation: Indonesian version\r\n        - country: Standard English country name\r\n        \r\n        EDITOR (Editor object, optional):\r\n        - original_script: Editor name in original script\r\n        - romanized: Romanized version\r\n        - Only include if editor is clearly identified\r\n        \r\n        DISTRIBUTOR_NAME (DistributorName object, optional):\r\n        - Same structure as publisher_name\r\n        - Only include if distributor is separate entity from publisher\r\n        \r\n        DISTRIBUTOR_LOCATION (DistributorLocation object, optional):\r\n        - Same structure as publisher_location\r\n        - Only include if distributor location differs from publisher\r\n        \r\n        CONFIDENCE: Your calculated confidence score (0.0-1.0)\r\n        \r\n        IMAGE_COUNT: {{total_images}}\r\n\r\n        ---\r\n\r\n        CRITICAL GUIDELINES:\r\n        ═══════════════════════════════════════════════════════════════════════════════\r\n        \r\n        ✓ Focus on colophon/copyright page as primary source\r\n        ✓ Carefully distinguish publisher from distributor, editor, and printer\r\n        ✓ Extract text EXACTLY as it appears in original script\r\n        ✓ Use standard transliteration systems for romanization\r\n        ✓ Ensure ASCII safety in romanized versions\r\n        ✓ Only include distributor if clearly separate from publisher\r\n        ✓ Only include editor if clearly identified (not just \"edited by publisher\")\r\n        ✓ Document reasoning at every step\r\n        ✓ Be honest about uncertainties\r\n        ✓ The final JSON may include comments explaining your reasoning\r\n        ✓ It's ok if the JSON isn't fully valid initially, we will clean it afterwards\r\n        ✓ Write a codeblock ONLY for the final JSON data containing your analysis\r\n        \r\n        ═══════════════════════════════════════════════════════════════════════════════\r\n\r\n        {{ ctx.output_format }}\r\n\r\n        {{ _.role(\"user\") }}\r\n        \r\n        BOOK IMAGES:\r\n        {% for image in MultiImages %}\r\n        Image {{loop.index}} of {{total_images}}: {{image}}\r\n        {% endfor %}\r\n        \r\n        TEAM MEMBER NOTES:\r\n        ---\r\n        {{RawVisualNote}}\r\n        ---\r\n        \r\n        Please analyze Book ID {{bookId}} following the 7-step workflow above. Focus especially on distinguishing between publisher, distributor, editor, and printer roles. Document your reasoning thoroughly, then provide the final structured publisher/distributor data.\r\n    \"#\r\n}",
    "bookRawData.baml": "class RawAnalysis {\r\n    coverPageDescription string @description(#\"\r\n        A complete list of all readable text and  detailed visual analysis of the cover page of the book from the given set of the images, including texts that are present on the cover page, including but not limited to the book's title, author(s), publisher, edition, and any other relevant information that can be found on the cover page.\r\n    \"#)\r\n    backCoverDescription string @description(#\"\r\n        A complete list of all readable text and detailed visual analysis of the back cover page of the book from the given set of the images, including texts that are present on the back cover page, including but not limited to the book's summary, author biography, publisher information, ISBN number and any other relevant information that can be found on the back cover page.\r\n    \"#)\r\n    colophonPageDescription string @description(#\"\r\n        A complete list of all readable text and detailed visual analysis of the colophon page of the book from the given set of the images, including texts that are present on the colophon page, including but not limited to the book's publication details, printing history, edition information, and any other relevant information that can be found on the colophon page.\r\n    \"#)\r\n    otherPageDescriptions string? @description(#\"\r\n        A complete list of all readable text and detailed visual analysis of the other pages of the book from the given set of the images, including texts that are present on the other pages, including but not limited to the book's alternative titles, forewords, prefaces, introductions, appendices, indexes, and any other relevant information that can be found on the other pages.\r\n    \"#)\r\n    }\r\n\r\nfunction GetBookrawVisual(MultiImages: image[], bookId: string) -> RawAnalysis {\r\n    client \"Gemini20FlashLite\"\r\n    prompt #\"\r\n        You are an expert librarian, and archivist. Your daily tasks is cataloging books, based on photos gathered by the field workers that visits libraries across the country. Your job in the team is to process the initial photos, and jot down in extreme detail, what each photo shows. This will be useful for other team members that will come after you, as they might not have access to the books directly or its photos, and therefore will rely on your detailed description to understand and catalogue the book.\r\n\r\n        You will receive 2 or more photos of a book. Each photo shows different parts of the book. Some books might have varying intactness. Some books might have damaged pages. Some books, might also have unusual layouts, or special pages. Some photos shows the front cover, some shows the back cover, some shows the colophon page, and some shows other pages. All photos are guaranteed to be of the same book, and is captured by the field team to gather as much information as possible about the book from the fieldwork.\r\n\r\n        You will analyze ALL images together to get the most complete and accurate information. Please write down any detail present on each part of the book shown in the photos. You should write down your analysis in the same format as the following example: \r\n        \r\n        \" This is a photo image number 1, it shows the front cover of the book. The cover has a blue background with an illustration of a tree in the center. The title of the book is \"The Great Adventure\" written in bold white letters at the top. The author's name, John Doe, is written in smaller white letters at the bottom. There is also a publisher's logo in the bottom right corner. \" . \r\n        \r\n        Please do this for each part of the book shown in the photos. Prioritize the analysis of the front cover, back cover, and colophon page. If any of these types of pages are not present, please note the absence in your analysis. In the case where you don't find another type of page, please also mention briefly your guess on what kind of page it might be, based on your analysis of the photo.\r\n        \r\n        After your thorough analysis, please relay the result of your analysis and extraction in the form of a JSON data, for each of the images you received. However, It's ok if this isn't fully valid JSON, we will fix it afterwards and remove the comments. But, please note that you should write a codeblock ONLY for the final JSON data containing only your analysis.\r\n\r\n        {{ ctx.output_format }}\r\n\r\n        {{ _.role(\"user\") }}\r\n        { _.role(\"user\") }}\r\n\r\n        Hi, the team at field have gathered the photos of this book, with the ID of {{bookId}}. Please analyze these book cover images and extract descriptive information about the book from the images.\r\n\r\n        {% for image in MultiImages %}\r\n        The image number {{loop.index}} is this image: {{image}}\r\n        {% endfor %}\r\n        \r\n        Extract comprehensive book data from all {{MultiImages|length}} images.\r\n    \"#\r\n}",
    "clients.baml": "// Learn more about clients at https://docs.boundaryml.com/docs/snippets/clients/overview\r\n\r\nclient<llm> CustomGPT4o {\r\n  provider openai\r\n  options {\r\n    model \"gpt-4o\"\r\n    api_key env.OPENAI_API_KEY\r\n  }\r\n}\r\n\r\nclient<llm> CustomGPT4oMini {\r\n  provider openai\r\n  retry_policy Exponential\r\n  options {\r\n    model \"gpt-4o-mini\"\r\n    api_key env.OPENAI_API_KEY\r\n  }\r\n}\r\n\r\nclient<llm> CustomSonnet {\r\n  provider anthropic\r\n  options {\r\n    model \"claude-3-5-sonnet-20241022\"\r\n    api_key env.ANTHROPIC_API_KEY\r\n  }\r\n}\r\n\r\n\r\nclient<llm> CustomHaiku {\r\n  provider anthropic\r\n  retry_policy Constant\r\n  options {\r\n    model \"claude-3-haiku-20240307\"\r\n    api_key env.ANTHROPIC_API_KEY\r\n  }\r\n}\r\n\r\nclient<llm> VisionModelQwen25_24b {\r\n  provider \"openai-generic\"\r\n  retry_policy Constant\r\n  options {\r\n    base_url \"https://openrouter.ai/api/v1\"\r\n    model \"qwen/qwen2.5-vl-32b-instruct\"\r\n    api_key env.OPENROUTER_KEY_PROD\r\n    temperature 0.8\r\n  }\r\n}\r\n\r\nclient<llm> Gemma327B {\r\n  provider \"openai-generic\"\r\n  options {\r\n    base_url \"https://openrouter.ai/api/v1\"\r\n    model \"google/gemma-3-27b-it\"\r\n    api_key env.OPENROUTER_KEY_PROD\r\n    temperature 0.8\r\n    headers {\r\n      \"X-Title\" \"YOUR-TITLE\" // Optional\r\n  }\r\n}}\r\n\r\nclient<llm> Gemini20FlashLite {\r\n  provider \"openai-generic\"\r\n  options {\r\n    base_url \"https://openrouter.ai/api/v1\"\r\n    model \"google/gemini-2.0-flash-lite-001\"\r\n    api_key env.OPENROUTER_KEY_PROD\r\n    retry_policy Constant\r\n    temperature 0.8\r\n    headers {\r\n      \"X-Title\" \"Ambarawa Book Info Retrieval\" // Optional\r\n  }\r\n}}\r\n\r\nclient<llm> InternVL_78B {\r\n  provider \"openai-generic\"\r\n  options {\r\n    base_url \"https://openrouter.ai/api/v1\"\r\n    model \"opengvlab/internvl3-78b\"\r\n    api_key env.OPENROUTER_KEY_PROD\r\n    temperature 0.8\r\n  }\r\n}\r\n\r\nclient<llm> THUDM_GLM_4_1V_9B_Thinking {\r\n  provider \"openai-generic\"\r\n  options {\r\n    base_url \"https://openrouter.ai/api/v1\"\r\n    model \"thudm/glm-4.1v-9b-thinking\"\r\n    api_key env.OPENROUTER_KEY_PROD\r\n    temperature 0.8\r\n  }\r\n}\r\n\r\n// Free models\r\n\r\nclient<llm> Grok4FastFree {\r\n  provider \"openai-generic\"\r\n  options {\r\n    base_url \"https://openrouter.ai/api/v1\"\r\n    model \"x-ai/grok-4-fast:free\"\r\n    api_key env.OPENROUTER_KEY_PROD\r\n    temperature 0.8\r\n  }\r\n}\r\n\r\nclient<llm> MistralSmall3_24bFree {\r\n  provider \"openai-generic\"\r\n  options {\r\n    base_url \"https://openrouter.ai/api/v1\"\r\n    model \"mistralai/mistral-small-3.2-24b-instruct:free\"\r\n    api_key env.OPENROUTER_KEY_PROD\r\n    temperature 0.8\r\n  }\r\n}\r\n\r\nclient<llm> LLama4MaverickFree {\r\n  provider \"openai-generic\"\r\n  options {\r\n    base_url \"https://openrouter.ai/api/v1\"\r\n    model \"meta-llama/llama-4-maverick:free\"\r\n    api_key env.OPENROUTER_KEY_PROD\r\n    temperature 0.8\r\n  }\r\n}\r\n\r\nclient<llm> Qwen2532bFree {\r\n  provider \"openai-generic\"\r\n  options {\r\n    base_url \"https://openrouter.ai/api/v1\"\r\n    model \"qwen/qwen2.5-vl-32b-instruct:free\"\r\n    api_key env.OPENROUTER_KEY_PROD\r\n    temperature 0.8\r\n  }\r\n}\r\n\r\nclient<llm> Mistral31_24bFree {\r\n  provider \"openai-generic\"\r\n  options {\r\n    base_url \"https://openrouter.ai/api/v1\"\r\n    model \"mistralai/mistral-small-3.1-24b-instruct:free\"\r\n    api_key env.OPENROUTER_KEY_PROD\r\n    temperature 0.8\r\n  }\r\n}\r\n\r\nclient<llm> Qwen25272bFree {\r\n  provider \"openai-generic\"\r\n  options {\r\n    base_url \"https://openrouter.ai/api/v1\"\r\n    model \"qwen/qwen2.5-vl-72b-instruct:free\"\r\n    api_key env.OPENROUTER_KEY_PROD\r\n    temperature 0.8\r\n  }\r\n}\r\n\r\n// Client with fallbacks to free models\r\nclient<llm> FreeLLMWithFallback {\r\n  provider fallback\r\n  options {\r\n    strategy [Qwen2532bFree, Qwen25272bFree, VisionModelQwen25_24b]\r\n  }\r\n}\r\n\r\n// https://docs.boundaryml.com/docs/snippets/clients/round-robin\r\nclient<llm> CustomFast {\r\n  provider round-robin\r\n  options {\r\n    // This will alternate between the two clients\r\n    strategy [CustomGPT4oMini, CustomHaiku]\r\n  }\r\n}\r\n\r\n// https://docs.boundaryml.com/docs/snippets/clients/fallback\r\nclient<llm> OpenaiFallback {\r\n  provider fallback\r\n  options {\r\n    // This will try the clients in order until one succeeds\r\n    strategy [CustomGPT4oMini, CustomGPT4oMini]\r\n  }\r\n}\r\n\r\n// https://docs.boundaryml.com/docs/snippets/clients/retry\r\nretry_policy Constant {\r\n  max_retries 3\r\n  // Strategy is optional\r\n  strategy {\r\n    type constant_delay\r\n    delay_ms 200\r\n  }\r\n}\r\n\r\nretry_policy Exponential {\r\n  max_retries 2\r\n  // Strategy is optional\r\n  strategy {\r\n    type exponential_backoff\r\n    delay_ms 300\r\n    multiplier 1.5\r\n    max_delay_ms 10000\r\n  }\r\n}",
    "generators.baml": "// This helps use auto generate libraries you can use in the language of\r\n// your choice. You can have multiple generators if you use multiple languages.\r\n// Just ensure that the output_dir is different for each generator.\r\ngenerator target {\r\n    // Valid values: \"python/pydantic\", \"typescript\", \"ruby/sorbet\", \"rest/openapi\"\r\n    output_type \"python/pydantic\"\r\n\r\n    // Where the generated code will be saved (relative to baml_src/)\r\n    output_dir \"../\"\r\n\r\n    // The version of the BAML package you have installed (e.g. same version as your baml-py or @boundaryml/baml).\r\n    // The BAML VSCode extension version should also match this version.\r\n    version \"0.215.0\"\r\n\r\n    // Valid values: \"sync\", \"async\"\r\n    // This controls what `b.FunctionName()` will be (sync or async).\r\n    default_client_mode sync\r\n}\r\n",
    "resume.baml": "// Defining a data model.\r\nclass Resume {\r\n  name string\r\n  email string\r\n  experience string[]\r\n  skills string[]\r\n}\r\n\r\n// Create a function to extract the resume from a string.\r\nfunction ExtractResume(resume: string) -> Resume {\r\n  // Specify a client as provider/model-name\r\n  // You can also use custom LLM params with a custom client name from clients.baml like \"client CustomGPT5\" or \"client CustomSonnet4\"\r\n  client \"openai-responses/gpt-5-mini\" // Set OPENAI_API_KEY to use this client.\r\n  prompt #\"\r\n    Extract from this content:\r\n    {{ resume }}\r\n\r\n    {{ ctx.output_format }}\r\n  \"#\r\n}\r\n\r\n\r\n\r\n// Test the function with a sample resume. Open the VSCode playground to run this.\r\ntest vaibhav_resume {\r\n  functions [ExtractResume]\r\n  args {\r\n    resume #\"\r\n      Vaibhav Gupta\r\n      vbv@boundaryml.com\r\n\r\n      Experience:\r\n      - Founder at BoundaryML\r\n      - CV Engineer at Google\r\n      - CV Engineer at Microsoft\r\n\r\n      Skills:\r\n      - Rust\r\n      - C++\r\n    \"#\r\n  }\r\n}\r\n",
}

def get_baml_files():
    return _file_map